def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Compute helper statistics
    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    my_c = 0
    for x in my:
        if x == 'C':
            my_c += 1

    last_me = my[-1]
    last_opp = opp[-1]

    remaining = 100 - n

    # Count runs at the end of opponent history
    def trailing_run(sym):
        c = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == sym:
                c += 1
            else:
                break
        return c

    def trailing_run_my(sym):
        c = 0
        for i in range(n - 1, -1, -1):
            if my[i] == sym:
                c += 1
            else:
                break
        return c

    # Very early: cooperate to establish mutual cooperation
    if n < 3:
        return 'C'

    opp_coop_rate = opp_c / n
    my_coop_rate = my_c / n

    # Endgame exploitation.  If opponent has been mostly cooperative, defect
    # to grab the 5 payoff, but be careful not to trigger a long punishment
    # spiral too far from the end.
    if remaining == 0:
        # final round
        return 'D' if opp_coop_rate >= 0.35 else 'D'

    if remaining <= 2:
        # Near end, defecting is nearly always at least as good unless the
        # opponent is very retaliatory.  Use last opponent action as signal.
        if opp_coop_rate > 0.45:
            return 'D'
        if last_opp == 'C':
            return 'D'
        # If opponent is almost always defecting, a C might catch a stray C,
        # but D guarantees at least 1.  Defect.
        return 'D'

    # If opponent has been almost entirely cooperative, keep cooperating but
    # occasionally exploit to boost score.  Use small probe rate so we don't
    # destroy cooperation.
    if opp_d == 0:
        if n >= 12 and remaining > 5:
            if rng.random() < 0.12:
                return 'D'
        return 'C'

    # If opponent is very defective, defect.
    if opp_coop_rate < 0.30:
        # But occasionally cooperate to try to restart mutual cooperation if
        # there is enough time left.
        if remaining > 20 and rng.random() < 0.06:
            return 'C'
        return 'D'

    # Detect long streaks of mutual cooperation and protect them.
    cc_streak = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and opp[i] == 'C':
            cc_streak += 1
        else:
            break
    if cc_streak >= 5:
        # In a good CC streak, only defect rarely and not near beginning
        if remaining > 3 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Detect opponent defection streak.
    opp_d_streak = trailing_run('D')
    my_d_streak = trailing_run_my('D')

    # If both are stuck in DD, try to break out with occasional C.
    if last_opp == 'D' and last_me == 'D':
        if opp_coop_rate > 0.4 and remaining > 10:
            if rng.random() < 0.20:
                return 'C'
        return 'D'

    # If we just defected while opponent cooperated, return to cooperation
    # (reward their continued cooperation) unless they seem exploitable.
    if last_me == 'D' and last_opp == 'C':
        if opp_coop_rate > 0.5:
            return 'C'
        # If opponent is moderately defective, keep pressing?  Better to
        # return to C to avoid long DD.
        return 'C'

    # If opponent just defected on our cooperation, retaliate once, then
    # consider forgiving if they have generally been cooperative.
    if last_me == 'C' and last_opp == 'D':
        # If opponent has had very few defections, forgive quickly.
        if opp_d <= max(1, n // 12) and remaining > 8:
            # single defection from a mostly cooperative opponent: forgive
            if rng.random() < 0.65:
                return 'C'
            return 'D'
        # If they defected twice in a row, punish harder.
        if opp_d_streak >= 2:
            return 'D'
        # Otherwise retaliate but with some forgiveness.
        if rng.random() < 0.25 and opp_coop_rate > 0.55:
            return 'C'
        return 'D'

    # Both cooperated last round: maintain cooperation with very small probe
    # rate only when opponent is not obviously punitive.
    if last_me == 'C' and last_opp == 'C':
        # If opponent has never/rarely defected, occasional probing is fine.
        if opp_d <= 2 and n > 15 and remaining > 5:
            if rng.random() < 0.04:
                return 'D'
        return 'C'

    # Fallback: copy opponent's last action.
    return last_opp
